    cout << fixed;
    //ll TL = 0.95 * CLOCKS_PER_SEC;
    //clock_t time = clock();
    int L, n, m;
    cin >> L >> n >> m;

    rep(i, 0, n)
    {
        int l, r;
        cin >> l >> r;
        add[l]++;
        add[r]--;
    }
    rep(i, 1, L + 1)
        add[i] += add[i - 1];

    fill(best, best + L + 1, inf);
    rep(i, 0, m)
    {
        int x, p;
        cin >> x >> p;
        setmin(best[x], p);
    }

    // dp[i] + best[i] * (j - i) = best[i] * j + (dp[i] - best[i] * i)
    build(L + 1);
    fill(dp, dp + L + 1, inf);
    dp[0] = 0;
    upd(0, 0, cnt_v, 0 + 1, cnt_v, Line(best[0], dp[0] - best[0] * 0));
    rep(i, 1, L + 1)
    {
        dp[i] = get(i);
        if (add[i - 1] == 0)
            setmin(dp[i], dp[i - 1]);
        upd(0, 0, cnt_v, i + 1, cnt_v, Line(best[i], dp[i] - best[i] * i));
    }
    cout << (dp[L] != inf ? dp[L] : -1) << "\n";
    return 0;
}
